use std :: sync :: Arc ; use forge_domain :: { TerminalCommand , TerminalContext } ; use crate :: EnvironmentInfra ; use std :: collections :: BTreeMap ; use std :: sync :: Arc ; use forge_domain :: { Environment , TerminalCommand , TerminalContext } ; use pretty_assertions :: assert_eq ; use super :: * ; use fake :: { Fake , Faker } ; # [doc = " Splits an `\\x1F`-separated (ASCII Unit Separator) environment variable"] # [doc = " value into a list of strings, filtering out any empty segments."] pub fn split_env_list (raw : & str) -> Vec < String > { raw . split (ENV_LIST_SEPARATOR) . filter (| s | ! s . is_empty ()) . map (String :: from) . collect () }